package io.github.cocokoniq.fancyir.core.data.catalog

import android.content.Context
import java.io.BufferedReader
import java.util.Properties
import java.util.zip.GZIPInputStream

/**
 * The catalog generated by tools/irdb-compiler, shipped in this module's assets. The file is
 * gzip but must not end in `.gz`: aapt treats those specially and strips the suffix.
 */
class AssetCatalog(context: Context) : CatalogAsset {

    private val assets = context.applicationContext.assets

    override val revision: String by lazy {
        Properties().apply { assets.open("$DIR/catalog.properties").use(::load) }.getProperty("revision", "unknown")
    }

    override fun open(): BufferedReader = GZIPInputStream(assets.open("$DIR/fancyir-catalog.tsv.gzip")).bufferedReader()

    private companion object {
        const val DIR = "catalog"
    }
}
